/// <summary>
/// PaffH 08.05.24
/// </summary>
/// <param name = "_nDXProdIdentProcedureLine1">NDXProdIdentProcedureLine1</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXProdIdentProcedureTable</returns>
public static NDXProdIdentProcedureTable findNDXProdIdentProcedureLine1(NDXProdIdentProcedureLine1 _nDXProdIdentProcedureLine1, boolean _selectForUpdate = true)
{
    NDXProdIdentProcedureTable nDXProdIdentProcedureTable;
    nDXProdIdentProcedureTable.selectForUpdate(_selectForUpdate);
    select firstonly *
        from nDXProdIdentProcedureTable
        where nDXProdIdentProcedureTable.RecId == _nDXProdIdentProcedureLine1.NDXProdIdentProcedureTable;
    return nDXProdIdentProcedureTable;
}

/// <summary>
/// PaffH 16.05.24
/// exist record for itemId
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <returns>record exists</returns>
public static boolean existsItemId(ItemId _itemId)
{
    NDXProdIdentProcedureTable nDXProdIdentProcedureTable;
    InventTable inventTable;
    select firstonly RecId from nDXProdIdentProcedureTable
        exists join inventTable
        where inventTable.RecId == nDXProdIdentProcedureTable.InventTable;
    return (nDXProdIdentProcedureTable.RecId > 0);

}

/// <summary>
/// PaffH 27.07.22
/// find by inventtable.recid
/// </summary>
/// <param name = "_inventTableRecId">RecId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>NDXProdIdentProcedureTable</returns>
public static NDXProdIdentProcedureTable findInventTable(RecId _inventTableRecId, boolean _selectForUpdate = true)
{
    NDXProdIdentProcedureTable nDXProdIdentProcedureTable;
    nDXProdIdentProcedureTable.selectForUpdate(_selectForUpdate);
    select firstonly * 
        from nDXProdIdentProcedureTable 
        where nDXProdIdentProcedureTable.InventTable == _inventTableRecId;
    return nDXProdIdentProcedureTable;
}

/// <summary>
/// PaffH 27.07.22
/// </summary>
/// <param name = "_inventTableRecId">RecId</param>
/// <param name = "insert">boolean</param>
/// <returns>NDXProdIdentProcedureTable</returns>
public static NDXProdIdentProcedureTable findOrCreateInventTable(RecId _inventTableRecId, boolean insert = true)
{
    NDXProdIdentProcedureTable nDXProdIdentProcedureTable = NDXProdIdentProcedureTable::findInventTable(_inventTableRecId, true);
    if (!nDXProdIdentProcedureTable)
    {
        nDXProdIdentProcedureTable.InventTable = _inventTableRecId;
        if (insert)
        {
            nDXProdIdentProcedureTable.insert();
        }
    }
    return nDXProdIdentProcedureTable;
}

/// <summary>
/// PaffH 18.08.22
/// count linked records in NDXProdIdentProcedureLine1
/// </summary>
/// <returns>count records</returns>
display NDXRecCountNDXProdIdentProcedureLine1 RecCountNDXProdIdentProcedureLine1()
{
    NDXProdIdentProcedureLine1 nDXProdIdentProcedureLine1;

    select count(RecId) from nDXProdIdentProcedureLine1
        where nDXProdIdentProcedureLine1.NDXProdIdentProcedureTable == this.RecId;

    return int642int(nDXProdIdentProcedureLine1.RecId);
}

/// <summary>
/// PaffH 18.08.22
/// count linked records in NDXProdIdentProcedureLine2
/// </summary>
/// <returns>count records</returns>
display NDXRecCountNDXProdIdentProcedureLine2 RecCountNDXProdIdentProcedureLine2()
{
    NDXProdIdentProcedureLine1 nDXProdIdentProcedureLine1;
    NDXProdIdentProcedureLine2 nDXProdIdentProcedureLine2;

    select count(RecId) from nDXProdIdentProcedureLine2
        join nDXProdIdentProcedureLine1
        where nDXProdIdentProcedureLine1.RecId == nDXProdIdentProcedureLine2.NDXProdIdentProcedureLine1
        && nDXProdIdentProcedureLine1.NDXProdIdentProcedureTable == this.RecId;

    return int642int(nDXProdIdentProcedureLine2.RecId);
}

