/// <summary>
/// PaffH 30.03.23
/// </summary>
/// <returns>number of AX2009 data transfer error messages</returns>
[SysClientCacheDataMethod]
display NDXCounterErrorMessagesAX2009DataTransfer CounterErrorMessagesAX2009Transfer()
{
    return NDXDataTransferError::find(this.TableId, this.RecId).CounterErrorMessages;
}
